"""Building the spec and ADR indexes, and comparing them with the files on disk."""

import re

from adrs import Adr, adr_name, parse_adr
from model import Problem, Texts
from specs import Spec, parse_spec, spec_name
from validate import folder_texts

NOTICE = (
    "> Generated by oekospec; do not edit by hand. "
    "Rebuild it with `python3 .agents/oekospec index`."
)
SENTENCE = re.compile(r"(.+?[.!?])(?=\s|$)")


def spec_index(specs: dict[str, Spec]) -> str:
    """docs/specs/index.md: each spec by name with link, first Purpose sentence and
    requirement names, under a generated notice."""
    lines = ["# Spec index", "", NOTICE, ""]
    for name in sorted(specs):
        spec = specs[name]
        lines.append(f"- [{name}]({name}.md): {_first_sentence(spec.purpose)}")
        lines += [f"  - {requirement.name}" for requirement in spec.requirements]
    return "\n".join(lines).rstrip("\n") + "\n"


def adr_index(adrs: dict[str, Adr]) -> str:
    """docs/adr/index.md: ADRs newest first with date, linked title and areas, superseded
    ones linked to their successor, under a generated notice."""
    dates = {name: adr.date for name, adr in adrs.items() if adr.date}
    adrs = {name: adrs[name] for name in dates}
    successor = {old: name for name, adr in adrs.items() for old in adr.supersedes}
    lines = ["# ADR index", "", NOTICE, ""]
    for name in sorted(adrs, key=lambda name: (-dates[name].toordinal(), name)):
        adr = adrs[name]
        line = f"- {dates[name].isoformat()} {_link(name, adr)} (areas: {', '.join(adr.areas)})"
        if name in successor and successor[name] in adrs:
            line += f", superseded by {_link(successor[name], adrs[successor[name]])}"
        lines.append(line)
    return "\n".join(lines).rstrip("\n") + "\n"


def build_indexes(texts: Texts) -> Texts:
    """Both indexes, built from the specs in docs/specs and the ADRs in docs/adr."""
    specs = {
        spec_name(path): parse_spec(path, text)[0]
        for path, text in folder_texts("docs/specs", texts).items()
    }
    adrs = {
        adr_name(adr): adr
        for adr in (parse_adr(path, text) for path, text in folder_texts("docs/adr", texts).items())
    }
    return {"docs/specs/index.md": spec_index(specs), "docs/adr/index.md": adr_index(adrs)}


def compare_index(path: str, current: str | None, wanted: str) -> list[Problem]:
    """A problem naming the index and the rebuild command if it differs from `wanted`."""
    if current == wanted:
        return []
    return [
        Problem(
            path, None, "index is out of date; rebuild it with `python3 .agents/oekospec index`"
        )
    ]


def _link(name: str, adr: Adr) -> str:
    return f"[{adr.title or name}]({name}.md)"


def _first_sentence(text: str) -> str:
    text = " ".join(text.split())
    match = SENTENCE.match(text)
    return match[1] if match else text
